drop policy if exists "Users can view own TALKZY profile" on public.talkzy_profiles;
drop policy if exists "Users can view profiles" on public.talkzy_profiles;
create policy "Users can view profiles" on public.talkzy_profiles for select to authenticated using (true);
drop policy if exists "Users can update own TALKZY profile" on public.talkzy_profiles;
drop policy if exists "Users can update own profile" on public.talkzy_profiles;
create policy "Users can update own profile" on public.talkzy_profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
drop policy if exists "Users can insert own TALKZY profile" on public.talkzy_profiles;
create policy "Users can insert own TALKZY profile" on public.talkzy_profiles for insert to authenticated with check ((select auth.uid())=id);
drop policy if exists "Users can view public rooms and own rooms" on public.talkzy_rooms;
drop policy if exists "Room participants can view room settings" on public.talkzy_rooms;
create policy "Room access read" on public.talkzy_rooms for select to authenticated using ((status='active' and room_type='public') or owner_id=(select auth.uid()) or (status='active' and (exists (select 1 from public.talkzy_room_members m where m.room_id=talkzy_rooms.id and m.user_id=(select auth.uid())) or exists (select 1 from public.talkzy_room_admins a where a.room_id=talkzy_rooms.id and a.user_id=(select auth.uid()))));
drop policy if exists "Users can view own admin assignment" on public.talkzy_room_admins;
create policy "Users can view own admin assignment" on public.talkzy_room_admins for select to authenticated using (user_id=(select auth.uid()));
drop policy if exists "Users can view own room membership" on public.talkzy_room_members;
create policy "Users can view own room membership" on public.talkzy_room_members for select to authenticated using (user_id=(select auth.uid()));
drop policy if exists "Users can view their own followed rooms" on public.talkzy_room_follows;
create policy "Users can view their own followed rooms" on public.talkzy_room_follows for select to authenticated using (user_id=(select auth.uid()));
drop policy if exists "Users can follow rooms" on public.talkzy_room_follows;
create policy "Users can follow rooms" on public.talkzy_room_follows for insert to authenticated with check (user_id=(select auth.uid()));
drop policy if exists "Users can unfollow their own rooms" on public.talkzy_room_follows;
create policy "Users can unfollow their own rooms" on public.talkzy_room_follows for delete to authenticated using (user_id=(select auth.uid()));
drop policy if exists "Users can read own room chat clear markers" on public.talkzy_room_chat_clears;
create policy "Users can read own room chat clear markers" on public.talkzy_room_chat_clears for select to authenticated using (user_id=(select auth.uid()));
create index if not exists talkzy_lucky_bag_claims_claimer_idx on public.talkzy_lucky_bag_claims(claimer_id);
create index if not exists talkzy_lucky_bags_sender_idx on public.talkzy_lucky_bags(sender_id);
create index if not exists talkzy_room_activities_created_by_idx on public.talkzy_room_activities(created_by);
create index if not exists talkzy_room_admins_user_idx on public.talkzy_room_admins(user_id);
create index if not exists talkzy_room_follows_room_idx on public.talkzy_room_follows(room_id);
create index if not exists talkzy_room_kicklist_kicked_by_idx on public.talkzy_room_kicklist(kicked_by);
create index if not exists talkzy_room_kicklist_user_idx on public.talkzy_room_kicklist(user_id);
create index if not exists talkzy_room_members_user_idx on public.talkzy_room_members(user_id);
create index if not exists talkzy_room_messages_sender_idx on public.talkzy_room_messages(sender_id);
create index if not exists talkzy_room_mic_seats_user_idx on public.talkzy_room_mic_seats(user_id);
create index if not exists talkzy_room_music_state_user_idx on public.talkzy_room_music_state(user_id);
create index if not exists talkzy_room_visitors_user_idx on public.talkzy_room_visitors(user_id);